6	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
7	
8	const TYPE_THRESHOLD = 3;
9	const POINTS_PER_SPHINX = 1;
10	const POINTS_WITHIN_THRESHOLD = 1;
11	const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;
12	
13	const countTypesSeenFrom = (index: number, army: Card[]): number =>
14	  new Set(
15	    army.filter((_card, other) => other !== index).map((card) => card.monster),
16	  ).size;
17	
18	const varietyPoints = (typeCount: number): number =>
19	  typeCount > TYPE_THRESHOLD
20	    ? POINTS_PER_TYPE_BEYOND_THRESHOLD * (typeCount - TYPE_THRESHOLD)
21	    : POINTS_WITHIN_THRESHOLD;
22	
23	const scoreOneSphinx = (typesSeenBySphinx: number): number =>
24	  POINTS_PER_SPHINX + varietyPoints(typesSeenBySphinx);
25	
26	export const scoreArmy = (army: Card[]): number =>
27	  army.reduce(
28	    (total, card, index) =>
29	      isSphinx(card) ? total + scoreOneSphinx(countTypesSeenFrom(index, army)) : total,
30	    0,
31	  );
